import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"交换论证","description":"","frontmatter":{"title":"交换论证","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exchange-argument.md","filePath":"cs/exchange-argument.md","lastUpdated":1789023840000}'),h={name:"cs/exchange-argument.md"};function _(E,a,u,m,A,g){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="交换论证" tabindex="-1">交换论证 <a class="header-anchor" href="#交换论证" aria-label="Permalink to &quot;交换论证&quot;">​</a></h1><div class="epigraph"><p>任取一份最优解，把它与贪心的第一步对换而不变差；重复对换，最优被改造成贪心序列。</p><footer>—— 据 CLRS 第 16 章；活动选择与 Huffman 的标准交换整理</footer></div><p>上一课<a href="/cs/greedy-correct">贪心正确性</a>已经命名「贪心选择性质 + 最优子结构」，并用活动选择点过交换。本课不重做「何时允许贪心」的总则。缺口是把<strong>交换</strong>写成可重复的手续：差异第一处、替换、代价不增、前缀与贪心一致。后课动态规划处理「不能证明只走一步」的枚举。本课只钉手续，不把 Huffman 树再证一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>贪心输出 \\(g_1,g_2,\\ldots\\)。最优 \\(OPT\\) 若 \\(g_1\\notin OPT\\)，要在 \\(OPT\\) 里找到可与 \\(g_1\\) 对换的元素（活动选择里那个结束更晚的第一件），换成 \\(g_1\\) 后仍可行且目标不差。于是存在最优包含 \\(g_1\\)。子问题同型，归纳得整份贪心最优。缺口是「对换哪两个、为何可行」，不是再列失败的密度背包。</p><p>与「领先论证」（stay-ahead）：证明贪心前 \\(i\\) 步在某度量上从不落后最优前 \\(i\\) 步。交换是改造最优；领先是同步比较。二者都接到最优，本课以交换为主，领先点名。</p><h3 id="交换不是任意互换" tabindex="-1">交换不是任意互换 <a class="header-anchor" href="#交换不是任意互换" aria-label="Permalink to &quot;交换不是任意互换&quot;">​</a></h3><p>必须保持可行：区间不重叠、树仍连、前缀码仍瞬时。只比目标值而不查可行，会把合法最优换成非法。拟阵上的交换公理保证总能换；本课不展开公理，只要求每一题单独证明可换。</p><p><span class="marginnote">CLRS 16.1 活动选择的交换是模板。Huffman 合并最小两棵是另一份。Kruskal 的安全边也是「换掉环上更贵的边」。算法课前面的 MST、Dijkstra 已用过，本课把手续抽出来对照 DP。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写贪心第一步 \\(g\\)。取最优 \\(O\\)。若 \\(g\\in O\\)，完。否则构造 \\(O&#39;=O-\\{x\\}\\cup\\{g\\}\\)，证 \\(O&#39;\\) 可行且 \\(c(O&#39;)\\le c(O)\\)（或最大化时 \\(\\ge\\)）。则 \\(g\\) 可出现在某最优中。对剩余输入重复。</p>',11)),(e(),s(p,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E8%B4%AA%E5%BF%83%E7%AC%AC%E4%B8%80%E6%AD%A5%20g%22%5D%20--%3E%20OPT%5B%22%E6%9F%90%E6%9C%80%E4%BC%98%20O%22%5D%0A%20%20OPT%20--%3E%20SW%5B%22%E6%8D%A2%E6%88%90%E5%90%AB%20g%20%E7%9A%84%20O'%22%5D%0A%20%20SW%20--%3E%20FEAS%5B%22%E4%BB%8D%E5%8F%AF%E8%A1%8C%E3%80%81%E4%B8%8D%E6%9B%B4%E5%B7%AE%22%5D%0A%20%20FEAS%20--%3E%20IND%5B%22%E5%AD%90%E9%97%AE%E9%A2%98%E5%BD%92%E7%BA%B3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>失败时给最小反例：任何对换都变差或不可行——那是后课 DP 或近似的入口，本课不硬贪。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>交换把「局部看起来好」变成「与某全局最优只差可修补的第一步」。最优子结构保证修补后的尾巴仍是子问题最优。没有子结构（最长简单路）时，换完尾巴可以不是原问题意义下的最优，手续中断。</p><p>不要把「排序后扫描」都叫交换：先排序可能只是实现，正确性仍要这一步对换或领先。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证拟阵。不写近似比（贪心 2-近似是更后的课）。0-1 背包反例只作对照。后课默认：能交换则贪心；不能则考虑把所有第一步都做成子问题——那就是动态规划。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交换：改造任意最优，使它含贪心第一步，目标不差。</li><li>领先是对照写法；拟阵是一类自动可换的结构，本课不展开。</li><li>接不上就不要贪心。</li><li>出处：CLRS 第 16 章。</li></ul>',8))])}const T=i(h,[["render",_]]);export{B as __pageData,T as default};
